@namespace sv_3195e7619e8045078cdc26af38b3f750.Components.Pages.Apply

<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    <div class="form-group">
        <label for="company-@Index">Company Name</label>
        <input id="company-@Index" type="text" value="@Entry.Company"
               @onchange="e => Update(Entry with { Company = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label for="title-@Index">Job Title</label>
        <input id="title-@Index" type="text" value="@Entry.Title"
               @onchange="e => Update(Entry with { Title = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label for="start-@Index">Start Date</label>
            <input id="start-@Index" type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>

        <div class="form-group">
            <label for="end-@Index">End Date</label>
            <input id="end-@Index" type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
                   disabled="@IsCurrent"
                   @onchange="e => Update(Entry with { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null })" />
        </div>

        <div class="form-group form-group-checkbox">
            <label>
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label for="desc-@Index">Description</label>
        <textarea id="desc-@Index" rows="3" value="@Entry.Description"
                  @onchange="e => Update(Entry with { Description = e.Value?.ToString() ?? string.Empty })"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        Update(updated);
    }

    private void Update(WorkEntryModel updated)
    {
        OnChanged.InvokeAsync(updated);
    }
}

