+            <CoverLetterStep CoverLetterText="@coverLetter"
+                             OnNext="HandleCoverLetterNext"
+                             OnBack="GoBack" />
+            break;
+        case 4:
+            <ReviewStep FullName="@fullName"
+                        Email="@email"
+                        Phone="@phone"
+                        Address="@address"
+                        WorkEntries="@workEntries"
+                        References="@references"
+                        CoverLetter="@coverLetter"
+                        IsSubmitting="@isSubmitting"
+                        IsSubmitted="@isSubmitted"
+                        ApplicationId="@applicationId"
+                        ErrorMessage="@submitError"
+                        OnSubmit="HandleSubmit"
+                        OnBack="GoBack"
+                        OnEditSection="GoToStep" />
+            break;
+    }
+</div>
+
+@code {
+    private int currentStep;
+    private int completedUpTo;
+
+    // Personal info state
+    private string fullName = string.Empty;
+    private string email = string.Empty;
+    private string phone = string.Empty;
+    private string address = string.Empty;
+
+    // Work history state
+    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
+
+    // References state
+    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Cover letter state
+    private string coverLetter = string.Empty;
+
+    // Submission state
+    private bool isSubmitting;
+    private bool isSubmitted;
+    private int applicationId;
+    private string? submitError;
+
+    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
+    {
+        fullName = result.FullName;
+        email = result.Email;
+        phone = result.Phone;
+        address = result.Address;
+        AdvanceTo(1);
+    }
+
+    private void HandleWorkHistoryNext(List<WorkEntryModel> entries)
+    {
+        workEntries = entries;
+        AdvanceTo(2);
+    }
+
+    private void HandleReferencesNext(List<ReferenceModel> refs)
+    {
+        references = refs;
+        AdvanceTo(3);
+    }
+
+    private void HandleCoverLetterNext(string text)
+    {
+        coverLetter = text;
+        AdvanceTo(4);
+    }
+
+    private async Task HandleSubmit()
+    {
+        isSubmitting = true;
+        submitError = null;
+
+        try
+        {
+            var workHistory = new WorkHistory(workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
+
+            var refList = references.Select(r =>
+                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+
+            var application = new JobApplication(
+                new PersonalInfo(fullName, email, phone, address),
+                workHistory,
+                refList,
+                coverLetter);
+
+            applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            isSubmitted = true;
+        }
+        catch (Exception ex)
+        {
+            submitError = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+
+    private void AdvanceTo(int step)
+    {
+        currentStep = step;
+        if (completedUpTo < step)
+            completedUpTo = step;
+    }
+
+    private void GoToStep(int step)
+    {
+        if (step <= completedUpTo)
+            currentStep = step;
+    }
+
+    private void GoBack()
+    {
+        if (currentStep > 0)
+            currentStep--;
+    }
+}
+

